// frontend/src/components/ConceptBoard.js
import React, { useRef, useState, useEffect } from "react";
import { fetchImages, uploadImage, updateImagePosition, deleteImage, checkServerConnection, updateImageSize } from '../api';

const ConceptBoard = () => {
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const [images, setImages] = useState([]);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });
  const [hoveredImageId, setHoveredImageId] = useState(null);
  const [resizingId, setResizingId] = useState(null);
  const [resizeStart, setResizeStart] = useState({ x: 0, y: 0, width: 0, height: 0 });

  const [showModal, setShowModal] = useState(false);
  const [pendingImage, setPendingImage] = useState(null);
  const [inputName, setInputName] = useState("");
  const [inputCategory, setInputCategory] = useState("");
  const [selectedLoreNoteId, setSelectedLoreNoteId] = useState('');
  const [loreNotes, setLoreNotes] = useState([]);

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [serverOnline, setServerOnline] = useState(false);

  const categories = [
    'Characters',
    'World Building', 
    'Music/Audio',
    'Technology',
    'Story/Plot',
    'Antagonists',
    'Environments',
    'Props',
    'Vehicles',
    'General'
  ];

  const categoryColors = {
    'Characters': '#EC4899',
    'World Building': '#00dbdd', 
    'Music/Audio': '#4ADE80',
    'Technology': '#f59e0b',
    'Story/Plot': '#8b5cf6',
    'Antagonists': '#FF3D3D',
    'Environments': '#10b981',
    'Props': '#f97316',
    'Vehicles': '#6366f1',
    'General': '#6b7280'
  };

  // Check server connection
  useEffect(() => {
    const checkServer = async () => {
      const isOnline = await checkServerConnection();
      setServerOnline(isOnline);
      if (!isOnline) {
        setErrorMessage("Server is offline. Make sure your backend is running on port 5000");
      }
    };
    
    checkServer();
  }, []);

  // Load data
  useEffect(() => {
    const loadData = async () => {
      if (!serverOnline) return;
      
      setIsLoading(true);
      try {
        const fetchedImages = await fetchImages();
        if (fetchedImages && Array.isArray(fetchedImages)) {
          const formattedImages = fetchedImages.map(img => ({
            id: img.id.toString(),
            src: `http://localhost:5000${img.url}`,
            x: img.posX || 100,
            y: img.posY || 100,
            name: img.name || img.originalName || 'Untitled',
            loreNoteId: img.loreNoteId ? img.loreNoteId.toString() : null,
            category: img.category || 'General',
            width: img.width || 300,
            height: img.height || 150
          }));
          setImages(formattedImages);
          localStorage.setItem('conceptBoard_images', JSON.stringify(formattedImages));
        }

        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }

      } catch (error) {
        console.error('Failed to load data:', error);
        setErrorMessage('Failed to load data. Check if server is running on port 5000.');
      } finally {
        setIsLoading(false);
      }
    };

    loadData();

    const handleLoreNotesStorageChange = (e) => {
      if (e.key === 'melodicJustice_loreNotes') {
        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }
      }
    };
    window.addEventListener('storage', handleLoreNotesStorageChange);
    return () => window.removeEventListener('storage', handleLoreNotesStorageChange);

  }, [serverOnline]);

  useEffect(() => {
    if (images.length > 0) {
      localStorage.setItem('conceptBoard_images', JSON.stringify(images));
    }
  }, [images]);

  // Get effective category
  const getEffectiveImageCategory = (image) => {
    if (image.loreNoteId && loreNotes.length > 0) {
      const linkedNote = loreNotes.find(note => note.id.toString() === image.loreNoteId);
      return linkedNote ? linkedNote.category : image.category;
    }
    return image.category;
  };

  // Add global mouse event listeners for reliable drag handling
  useEffect(() => {
    const handleGlobalMouseUp = async () => {
      if (draggingId) {
        const image = images.find(img => img.id === draggingId);
        if (image) {
          try {
            await updateImagePosition(draggingId, image.x, image.y);
          } catch (error) {
            console.error('Failed to update position:', error);
          }
        }
        setDraggingId(null);
        setDragOffset({ x: 0, y: 0 });
      }
      
      if (resizingId) {
        const image = images.find(img => img.id === resizingId);
        if (image) {
          try {
            await updateImageSize(resizingId, image.width, image.height);
          } catch (error) {
            console.error('Failed to update size:', error);
          }
        }
        setResizingId(null);
      }
      
      setIsPanning(false);
    };

    const handleGlobalMouseMove = (e) => {
      if (draggingId && !resizingId) {
        const rect = boardRef.current?.getBoundingClientRect();
        if (!rect) return;
        
        const boardX = (e.clientX - rect.left - transform.x) / transform.scale;
        const boardY = (e.clientY - rect.top - transform.y) / transform.scale;
        
        const newX = Math.max(0, boardX - dragOffset.x);
        const newY = Math.max(0, boardY - dragOffset.y);
        
        setImages(prev => prev.map(img => 
          img.id === draggingId ? { ...img, x: newX, y: newY } : img
        ));
      } else if (resizingId) {
        const rect = boardRef.current?.getBoundingClientRect();
        if (!rect) return;
        
        const mouseX = (e.clientX - rect.left - transform.x) / transform.scale;
        const mouseY = (e.clientY - rect.top - transform.y) / transform.scale;
        
        const deltaX = mouseX - resizeStart.x;
        const deltaY = mouseY - resizeStart.y;
        
        const newWidth = Math.max(50, resizeStart.width + deltaX);
        const newHeight = Math.max(50, resizeStart.height + deltaY);
        
        setImages(prev => prev.map(img => 
          img.id === resizingId ? { ...img, width: newWidth, height: newHeight } : img
        ));
      } else if (isPanning) {
        const deltaX = e.clientX - panStart.x;
        const deltaY = e.clientY - panStart.y;
        
        setTransform(prev => ({
          ...prev,
          x: prev.x + deltaX,
          y: prev.y + deltaY
        }));
        
        setPanStart({ x: e.clientX, y: e.clientY });
      }
    };

    // Add global event listeners
    document.addEventListener('mouseup', handleGlobalMouseUp);
    document.addEventListener('mousemove', handleGlobalMouseMove);
    
    // Cleanup
    return () => {
      document.removeEventListener('mouseup', handleGlobalMouseUp);
      document.removeEventListener('mousemove', handleGlobalMouseMove);
    };
  }, [draggingId, resizingId, isPanning, dragOffset, transform, resizeStart, panStart, images]);

  // Event handlers
  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      setPendingImage(file);
      setInputName(`Image ${images.length + 1}`);
      setInputCategory('General');
      setSelectedLoreNoteId('');
      setShowModal(true);
    }
  };

  const handleUploadConfirm = async () => {
    if (!pendingImage) return;

    setIsUploading(true);
    try {
      const uploadData = {
        name: inputName,
        category: inputCategory,
        loreNoteId: selectedLoreNoteId || null,
        x: 100,
        y: 100,
        width: 300,
        height: 200
      };

      const uploadedImage = await uploadImage(pendingImage, uploadData);
      
      if (uploadedImage) {
        const newImage = {
          id: uploadedImage.id.toString(),
          src: `http://localhost:5000${uploadedImage.url}`,
          x: uploadedImage.x || 100,
          y: uploadedImage.y || 100,
          name: uploadedImage.name,
          loreNoteId: uploadedImage.loreNoteId ? uploadedImage.loreNoteId.toString() : null,
          category: uploadedImage.category,
          width: uploadedImage.width || 300,
          height: uploadedImage.height || 200
        };
        
        setImages(prev => [...prev, newImage]);
      }

    } catch (error) {
      console.error('Upload failed:', error);
      setErrorMessage('Failed to upload image. Please try again.');
    } finally {
      setIsUploading(false);
      setShowModal(false);
      setPendingImage(null);
      setInputName("");
      setInputCategory("");
      setSelectedLoreNoteId('');
    }
  };

  const handleUpdateImageCategory = async (imageId, category, loreNoteId) => {
    try {
      const response = await fetch(`http://localhost:5000/api/images/${imageId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category, loreNoteId })
      });

      if (response.ok) {
        setImages(prev => prev.map(img => 
          img.id === imageId 
            ? { ...img, category: category || img.category, loreNoteId }
            : img
        ));
      }
    } catch (error) {
      console.error('Failed to update image:', error);
    }
  };

  const handleDeleteImage = async (imageId) => {
    try {
      await deleteImage(imageId);
      setImages(prev => prev.filter(img => img.id !== imageId));
    } catch (error) {
      console.error('Failed to delete image:', error);
    }
  };

  const handleMouseDown = (e, imageId) => {
    if (resizingId) return;
    
    const rect = boardRef.current.getBoundingClientRect();
    const clientX = e.clientX;
    const clientY = e.clientY;
    
    const boardX = (clientX - rect.left - transform.x) / transform.scale;
    const boardY = (clientY - rect.top - transform.y) / transform.scale;
    
    const image = images.find(img => img.id === imageId);
    if (image) {
      setDraggingId(imageId);
      setDragOffset({
        x: boardX - image.x,
        y: boardY - image.y
      });
    }
  };

  const handleMouseMove = (e) => {
    // This function is now only used for board-level events
    // Individual dragging/resizing is handled by global listeners
  };

  const handleMouseUp = async () => {
    // This function is now only used for board-level events
    // Individual dragging/resizing is handled by global listeners
  };

  const handleResizeMouseDown = (e, imageId, corner) => {
    e.stopPropagation();
    const image = images.find(img => img.id === imageId);
    if (image) {
      const rect = boardRef.current.getBoundingClientRect();
      const mouseX = (e.clientX - rect.left - transform.x) / transform.scale;
      const mouseY = (e.clientY - rect.top - transform.y) / transform.scale;
      
      setResizingId(imageId);
      setResizeStart({
        x: mouseX,
        y: mouseY,
        width: image.width,
        height: image.height
      });
    }
  };

  const handleBoardMouseDown = (e) => {
    if (e.target === boardRef.current) {
      setIsPanning(true);
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const rect = boardRef.current.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    const newScale = Math.max(0.1, Math.min(3, transform.scale * delta));
    
    const scaleChange = newScale / transform.scale;
    const newX = mouseX - (mouseX - transform.x) * scaleChange;
    const newY = mouseY - (mouseY - transform.y) * scaleChange;
    
    setTransform({ scale: newScale, x: newX, y: newY });
  };

  const toggleFullscreen = () => {
    if (!isFullscreen) {
      boardRef.current.requestFullscreen?.();
    } else {
      document.exitFullscreen?.();
    }
    setIsFullscreen(!isFullscreen);
  };

  return (
    <div className="h-screen bg-gray-900 text-white relative overflow-hidden">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 z-10 bg-gray-900 bg-opacity-90 backdrop-blur-sm p-4 flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Concept Board</h1>
          <p className="text-gray-400 text-sm">Organize and manage concept art and reference images</p>
          <div className="flex items-center mt-1">
            <div className={`w-2 h-2 rounded-full mr-2 ${serverOnline ? 'bg-green-500' : 'bg-red-500'}`}></div>
            <span className="text-xs text-gray-400">
              {serverOnline ? 'Server Connected' : 'Server Offline'}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={!serverOnline || isUploading}
            className="px-4 py-2 bg-teal-600 hover:bg-teal-700 rounded-lg transition-colors disabled:opacity-50"
          >
            {isUploading ? 'Uploading...' : '+ Add Image'}
          </button>
          <button
            onClick={toggleFullscreen}
            className="px-4 py-2 bg-gray-700 hover:bg-gray-600 rounded-lg transition-colors"
          >
            {isFullscreen ? 'Exit' : 'Fullscreen'}
          </button>
        </div>
      </div>

      {/* Error message */}
      {errorMessage && (
        <div className="absolute top-20 left-4 right-4 z-20 bg-red-900 bg-opacity-90 text-white p-3 rounded-lg">
          <button 
            onClick={() => setErrorMessage(null)}
            className="float-right ml-2 text-red-300 hover:text-white"
          >
            ×
          </button>
          {errorMessage}
        </div>
      )}

      {/* Main board */}
      <div
        ref={boardRef}
        className="w-full h-full"
        onMouseDown={handleBoardMouseDown}
        onWheel={handleWheel}
        style={{
          cursor: isPanning ? "grabbing" : "grab",
        }}
      >
        <div
          style={{
            transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
            transformOrigin: "0 0",
            position: "absolute",
            top: 0,
            left: 0,
          }}
        >
          {images.map((img) => {
            const effectiveCategory = getEffectiveImageCategory(img);
            return (
              <div
                key={img.id}
                style={{
                  position: "absolute",
                  left: img.x,
                  top: img.y,
                  width: img.width,
                  cursor: draggingId === img.id ? "grabbing" : "move",
                  userSelect: "none",
                  borderRadius: "8px",
                  padding: "0px",
                  transition: "box-shadow 0.2s ease-in-out",
                  boxShadow: hoveredImageId === img.id 
                    ? "0 8px 32px rgba(0,0,0,0.4)" 
                    : "0 4px 16px rgba(0,0,0,0.3)",
                  zIndex: hoveredImageId === img.id ? 100 : 1,
                }}
                onMouseDown={(e) => handleMouseDown(e, img.id)}
                onMouseEnter={() => setHoveredImageId(img.id)}
                onMouseLeave={() => setHoveredImageId(null)}
              >
                {/* Delete button */}
                {hoveredImageId === img.id && (
                  <div className="absolute -top-2 -right-2 z-10">
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteImage(img.id);
                      }}
                      className="w-8 h-8 bg-red-500 text-white rounded-full flex items-center justify-center 
                                 shadow-lg hover:bg-red-600 transition-colors"
                    >
                      <span className="text-lg leading-none">×</span>
                    </button>
                  </div>
                )}
                
                <img
                  src={img.src}
                  alt={img.name}
                  style={{
                    width: "100%",
                    height: "100%",
                    borderRadius: "8px",
                    pointerEvents: "none",
                    objectFit: "cover",
                    display: "block",
                  }}
                  draggable={false}
                />
                
                {/* Resize handles */}
                {hoveredImageId === img.id && (
                  <>
                    <div
                      className="absolute bottom-0 right-0 w-4 h-4 bg-white border border-gray-400 cursor-se-resize"
                      onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'se')}
                      style={{ transform: 'translate(50%, 50%)' }}
                    />
                    <div
                      className="absolute bottom-0 left-0 w-4 h-4 bg-white border border-gray-400 cursor-sw-resize"
                      onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'sw')}
                      style={{ transform: 'translate(-50%, 50%)' }}
                    />
                    <div
                      className="absolute top-0 right-0 w-4 h-4 bg-white border border-gray-400 cursor-ne-resize"
                      onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'ne')}
                      style={{ transform: 'translate(50%, -50%)' }}
                    />
                    <div
                      className="absolute top-0 left-0 w-4 h-4 bg-white border border-gray-400 cursor-nw-resize"
                      onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'nw')}
                      style={{ transform: 'translate(-50%, -50%)' }}
                    />
                  </>
                )}
                
                {/* Fixed dropdown positioning - positioned at bottom of image */}
                {hoveredImageId === img.id && (
                  <div 
                    className="absolute bg-black bg-opacity-90 border border-gray-600 rounded-b-lg shadow-xl p-3"
                    style={{
                      bottom: 0, // Position at bottom of image
                      left: 0,
                      right: 0,
                      zIndex: 1001, // Higher than other elements
                    }}
                  >
                    <div className="text-white text-center mb-2">
                      <div className="font-semibold text-sm text-gray-200">{img.name}</div>
                    </div>
                    
                    <div className="relative">
                      <select
                        value={img.loreNoteId ? `loreNote-${img.loreNoteId}` : 'unlinked'}
                        onChange={(e) => {
                          const value = e.target.value;
                          if (value.startsWith('loreNote-')) {
                            const noteId = value.substring('loreNote-'.length);
                            handleUpdateImageCategory(img.id, null, noteId);
                          } else if (value === 'unlink') {
                            handleUpdateImageCategory(img.id, 'General', null);
                          }
                        }}
                        onClick={(e) => e.stopPropagation()}
                        className="w-full text-xs px-3 py-2 rounded-lg bg-gray-700 text-white border border-gray-500 cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                        style={{ 
                          backgroundColor: '#374151',
                          color: '#ffffff'
                        }}
                      >
                        <option value="unlinked" style={{ backgroundColor: '#1f2937' }}>
                          {img.loreNoteId ? 'Select different note or unlink' : 'Link to LoreNote'}
                        </option>
                        
                        {img.loreNoteId && (
                          <option value="unlink" style={{ backgroundColor: '#1f2937', color: '#ef4444' }}>
                            🔓 Unlink from LoreNote
                          </option>
                        )}
                        
                        {loreNotes.length > 0 && loreNotes.map(note => (
                          <option 
                            key={`loreNote-${note.id}`} 
                            value={`loreNote-${note.id}`}
                            style={{ 
                              backgroundColor: '#1f2937', 
                              color: note.color || '#ffffff',
                              padding: '8px 12px'
                            }}
                          >
                            🔗 {note.title} ({note.category})
                          </option>
                        ))}
                      </select>
                    </div>
                    
                    {/* Category indicator - only show if linked */}
                    {img.loreNoteId && (
                      <div className="mt-2 text-center">
                        <span 
                          className="inline-block px-2 py-1 rounded-full text-xs font-medium"
                          style={{
                            backgroundColor: `${categoryColors[effectiveCategory] || '#6b7280'}20`,
                            color: categoryColors[effectiveCategory] || '#9ca3af',
                            border: `1px solid ${categoryColors[effectiveCategory] || '#6b7280'}40`
                          }}
                        >
                          {effectiveCategory}
                        </span>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Empty state */}
        {images.length === 0 && !isLoading && (
          <div style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            color: '#777'
          }}>
            <p style={{ marginBottom: '10px' }}>No concept images added yet</p>
            {serverOnline ? (
              <p style={{ fontSize: '14px' }}>Click "Add Image" to get started</p>
            ) : (
              <p style={{ fontSize: '14px', color: '#ff6b6b' }}>Start your server to begin adding images</p>
            )}
          </div>
        )}

        {/* Loading indicator */}
        {isLoading && (
          <div style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            color: '#777'
          }}>
            <p>Loading images...</p>
          </div>
        )}
      </div>

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        onChange={handleFileSelect}
        style={{ display: 'none' }}
      />

      {/* Upload Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-800 rounded-lg p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-bold mb-4">Add New Image</h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Name</label>
                <input
                  type="text"
                  value={inputName}
                  onChange={(e) => setInputName(e.target.value)}
                  className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500"
                  placeholder="Enter image name"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Link to LoreNote (Optional)</label>
                <select
                  value={selectedLoreNoteId}
                  onChange={(e) => {
                    setSelectedLoreNoteId(e.target.value);
                    if (e.target.value) {
                      const selectedNote = loreNotes.find(note => note.id.toString() === e.target.value);
                      if (selectedNote) {
                        setInputCategory(selectedNote.category);
                      }
                    }
                  }}
                  className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500"
                >
                  <option value="">No link to LoreNote</option>
                  {loreNotes.map(note => (
                    <option key={note.id} value={note.id.toString()}>
                      {note.title} ({note.category})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Category</label>
                <select
                  value={inputCategory}
                  onChange={(e) => setInputCategory(e.target.value)}
                  disabled={selectedLoreNoteId} // Disable if linked to lore note
                  className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 disabled:opacity-50"
                >
                  {categories.map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
                {selectedLoreNoteId && (
                  <p className="text-xs text-gray-400 mt-1">
                    Category automatically set from linked LoreNote
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => {
                  setShowModal(false);
                  setPendingImage(null);
                }}
                className="px-4 py-2 text-gray-400 hover:text-white transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleUploadConfirm}
                disabled={!inputName.trim() || isUploading}
                className="px-4 py-2 bg-teal-600 hover:bg-teal-700 rounded-lg transition-colors disabled:opacity-50"
              >
                {isUploading ? 'Uploading...' : 'Upload'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ConceptBoard;
